// Copies the shared sound effects from packages/shared-assets/sounds/ into
// public/sounds/ so Angular CLI's asset pipeline (which can't glob outside the
// workspace root) picks them up and serves them at /angular/sounds/<name>.mp3.
// React copies the same source directory via scripts/copy-shared-assets.mjs;
// this keeps Angular on the identical audio files without a second copy in
// git (public/sounds/ is gitignored and regenerated by this script).
import { cpSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const source = join(here, '..', '..', 'packages', 'shared-assets', 'sounds');
const dest = join(here, '..', 'public', 'sounds');

rmSync(dest, { recursive: true, force: true });
cpSync(source, dest, { recursive: true });
